const upsertPushSubscription = `-- name: UpsertPushSubscription :one

INSERT INTO push_subscriptions (
    account_id, session_id, endpoint, endpoint_host, p256dh, auth, created_at
) VALUES (
    $1::bigint,
    $2::text,
    $3::text,
    $4::text,
    $5::text,
    $6::text,
    $7::timestamptz
)
ON CONFLICT (endpoint) DO UPDATE
SET account_id = EXCLUDED.account_id,
    session_id = EXCLUDED.session_id,
    endpoint_host = EXCLUDED.endpoint_host,
    p256dh = EXCLUDED.p256dh,
    auth = EXCLUDED.auth,
    created_at = EXCLUDED.created_at,
    last_ok_at = NULL,
    failures = 0
RETURNING id
`

type UpsertPushSubscriptionParams struct {
	AccountID    int64
	SessionID    string
	Endpoint     string
	EndpointHost string
	P256dh       string
	Auth         string
	Now          time.Time
}

// Phase 3.3 queries: phone alert subscriptions, the recipient candidate read,
// the send queue (outbox) and the per report fan out bookkeeping. SQL never
// decides visibility (TRUST-02): the Go resolver does, and these queries only
// select candidates and hand the worker raw facts.
//
// A live subscription, wherever a query says so, is a push_subscriptions row
// joined to sessions on session_id with sessions.revoked_at IS NULL, for an
// account whose accounts.deleted_at IS NULL.
//
// Privacy rules the queries keep: the endpoint is a capability URL and is
// returned by exactly one query (PushSubscriptionsForAccount, the send path);
// the recipient candidate read selects accounts by their home cell and returns
// no position of any kind; only PushReportFacts, which is read by server code
// alone, returns a report's position, for the distance. No query here reads a
// voter cell.
//
// Every write that carries a time takes it as an argument, so tests can pin the
// clock. The claim and the lease marks use the database clock for the lease,
// like the moderation worker does.
// Registers a device (D-13). The endpoint is unique, so the same endpoint
// registered by another account moves to the caller: a shared phone must stop
// delivering the previous account's alerts, and the failure count starts over.
func (q *Queries) UpsertPushSubscription(ctx context.Context, arg UpsertPushSubscriptionParams) (int64, error) {
	row := q.db.QueryRow(ctx, upsertPushSubscription,
		arg.AccountID,
		arg.SessionID,
		arg.Endpoint,
		arg.EndpointHost,
		arg.P256dh,
		arg.Auth,
		arg.Now,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const voteLogForReport = `-- name: VoteLogForReport :many
SELECT report_id, account_id, kind, value, geohash_cell, created_at
FROM votes
WHERE report_id = $1::bigint
ORDER BY created_at, id
`

type VoteLogForReportRow struct {
	ReportID    int64
	AccountID   int64
	Kind        string
	Value       string
	GeohashCell string
	CreatedAt   time.Time
}

// The worker replays this to decide whether a report had been confirmed before a
// now disputed note may reach a phone (03.3-UAT gap for test 8, 2026-10-28).
// votes is an append only log, so these rows in order are the report's whole
// vote history. It returns raw facts only and SQL decides nothing (TRUST-02): the
// Go resolver replays them through BuildVoteTally, Resolve and ConfirmedByPeople.
func (q *Queries) VoteLogForReport(ctx context.Context, reportID int64) ([]VoteLogForReportRow, error) {
	rows, err := q.db.Query(ctx, voteLogForReport, reportID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []VoteLogForReportRow
	for rows.Next() {
		var i VoteLogForReportRow
		if err := rows.Scan(
			&i.ReportID,
			&i.AccountID,
			&i.Kind,
			&i.Value,
			&i.GeohashCell,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
